                                stack.append((nr, nc))

                # Keep connected component if it has at least 2 cells
                if len(cells) >= 2:
                    # Find bounding box
                    min_r, max_r = min(cell[0] for cell in cells), max(cell[0] for cell in cells)
                    min_c, max_c = min(cell[1] for cell in cells), max(cell[1] for cell in cells)
                    # Fill the entire bounding box with the same color
                    for i in range(min_r, max_r + 1):
                        for j in range(min_c, max_c + 1):
                            output[i][j] = color

    return output

